func (writer *RecordingDescriptor) String() string {
    var builder strings.Builder
    builder.WriteString("{\"Name\": \"RecordingDescriptor\", ")
    builder.WriteString(fmt.Sprintf("\"sbeTemplateId\": %d", writer.SbeTemplateId()))
    builder.WriteString(", ")

    builder.WriteString(`"controlSessionId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.ControlSessionId()))

    builder.WriteString(", ")
    builder.WriteString(`"correlationId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.CorrelationId()))

    builder.WriteString(", ")
    builder.WriteString(`"recordingId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.RecordingId()))

    builder.WriteString(", ")
    builder.WriteString(`"startTimestamp": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.StartTimestamp()))

    builder.WriteString(", ")
    builder.WriteString(`"stopTimestamp": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.StopTimestamp()))

    builder.WriteString(", ")
    builder.WriteString(`"startPosition": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.StartPosition()))

    builder.WriteString(", ")
    builder.WriteString(`"stopPosition": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.StopPosition()))

    builder.WriteString(", ")
    builder.WriteString(`"initialTermId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.InitialTermId()))

    builder.WriteString(", ")
    builder.WriteString(`"segmentFileLength": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.SegmentFileLength()))

    builder.WriteString(", ")
    builder.WriteString(`"termBufferLength": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.TermBufferLength()))

    builder.WriteString(", ")
    builder.WriteString(`"mtuLength": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.MtuLength()))

    builder.WriteString(", ")
    builder.WriteString(`"sessionId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.SessionId()))

    builder.WriteString(", ")
    builder.WriteString(`"streamId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.StreamId()))

    builder.WriteString(", ")
    builder.WriteString(`"strippedChannel": `)
    builder.WriteString(`"` + writer.GetStrippedChannelAsJsonEscapedString() + `"`);

    builder.WriteString(", ")
    builder.WriteString(`"originalChannel": `)
    builder.WriteString(`"` + writer.GetOriginalChannelAsJsonEscapedString() + `"`);

    builder.WriteString(", ")
    builder.WriteString(`"sourceIdentity": `)
    builder.WriteString(`"` + writer.GetSourceIdentityAsJsonEscapedString() + `"`);

    builder.WriteString("}")

    return builder.String()
}

func (m *RecordingDescriptor) Skip() {
    m.SkipStrippedChannel()
    m.SkipOriginalChannel()
    m.SkipSourceIdentity()
}

func (m *RecordingDescriptor) IsConstLength() bool {
    return false
}

func (m *RecordingDescriptor) ComputeLength(
     StrippedChannelLength int,
     OriginalChannelLength int,
     SourceIdentityLength int) (int, error) {
    length := uint64(m.SbeBlockLength())

    length += m.StrippedChannelHeaderLength()
    if m.StrippedChannelLength() > 1073741824 {
        return 0, fmt.Errorf("StrippedChannelLength too long for length type [E109]")
    }
    length += uint64(m.StrippedChannelLength())

    length += m.OriginalChannelHeaderLength()
    if m.OriginalChannelLength() > 1073741824 {
        return 0, fmt.Errorf("OriginalChannelLength too long for length type [E109]")
    }
    length += uint64(m.OriginalChannelLength())

    length += m.SourceIdentityHeaderLength()
    if m.SourceIdentityLength() > 1073741824 {
        return 0, fmt.Errorf("SourceIdentityLength too long for length type [E109]")
    }
    length += uint64(m.SourceIdentityLength())

    return int(length), nil
}
